const GetAchievementsFilteredCursor = `-- name: GetAchievementsFilteredCursor :many
SELECT
    a.id,
    a.achievement_type,
    a.project_id,
    a.event_id,
    a.challenge_id,
    a.name,
    a.description_pending,
    a.description_completed,
    a.notification_text,
    a.image_pending,
    a.image_completed,
    a.points,
    a.hidden,
    a.awardable_from,
    a.sort_order,
    a.created_at,
    a.updated_at,
    -- Content achievement data
    ca.achievement_id AS content_achievement_id,
    COALESCE(
        (SELECT jsonb_agg(
            jsonb_build_object(
                'id', cai.id,
                'external_content_id', cai.external_content_id,
                'sort_order', cai.sort_order
            ) ORDER BY cai.sort_order
        )
        FROM content_achievement_items cai
        WHERE cai.achievement_id = a.id),
        '[]'::jsonb
    ) AS content_items,
    -- Streak achievement data
    sa.achievement_id AS streak_achievement_id,
    COALESCE(
        (SELECT jsonb_agg(
            jsonb_build_object(
                'id', sai.id,
                'external_content_id', sai.external_content_id,
                'sort_order', sai.sort_order
            ) ORDER BY sai.sort_order
        )
        FROM streak_achievement_items sai
        WHERE sai.achievement_id = a.id),
        '[]'::jsonb
    ) AS streak_items,
    -- Quiz achievement data
    qa.quiz_id,
    qa.min_score_percentage,
    qa.require_completion
FROM achievements a
LEFT JOIN content_achievements ca ON a.id = ca.achievement_id
LEFT JOIN streak_achievements sa ON a.id = sa.achievement_id
LEFT JOIN quiz_achievements qa ON a.id = qa.achievement_id
WHERE
    ($1::text[] IS NULL OR a.id = ANY($1::text[]))
    AND ($2::text = '' OR a.project_id = $2::text)
    AND ($3::text = '' OR a.event_id = $3::text)
    AND ($4::text = '' OR (a.sort_order, a.id) > (SELECT sort_order, id FROM achievements WHERE id = $4::text))
    AND ($5::text = '' OR (a.sort_order, a.id) < (SELECT sort_order, id FROM achievements WHERE id = $5::text))
ORDER BY
    CASE WHEN $6::bool = true THEN a.sort_order END DESC,
    CASE WHEN $6::bool = false OR $6::bool IS NULL THEN a.sort_order END ASC,
    CASE WHEN $6::bool = true THEN a.id END DESC,
    CASE WHEN $6::bool = false OR $6::bool IS NULL THEN a.id END ASC
LIMIT CASE WHEN $7::int IS NULL THEN NULL ELSE $7::int END
`

